	"/manifest.webmanifest": { body: "{\n\t\"name\": \"OMPx Session Kanban\",\n\t\"short_name\": \"OMPx Kanban\",\n\t\"description\": \"Local task board for an interactive OMPx session.\",\n\t\"start_url\": \"/kanban/\",\n\t\"scope\": \"/kanban/\",\n\t\"display\": \"standalone\",\n\t\"background_color\": \"#0f0b14\",\n\t\"theme_color\": \"#0f0b14\",\n\t\"icons\": [\n\t\t{ \"src\": \"/favicon.svg\", \"type\": \"image/svg+xml\", \"sizes\": \"any\", \"purpose\": \"any\" },\n\t\t{ \"src\": \"/favicon-192x192.png\", \"type\": \"image/png\", \"sizes\": \"192x192\", \"purpose\": \"any maskable\" },\n\t\t{ \"src\": \"/favicon-512x512.png\", \"type\": \"image/png\", \"sizes\": \"512x512\", \"purpose\": \"any maskable\" }\n\t]\n}\n", contentType: "application/manifest+json; charset=utf-8", cacheControl: "no-cache" },
	"/sw.js": { body: "const CACHE_NAME = \"ompx-kanban-shell-v1\";\nconst SHELL_URLS = [\n\t\"/\",\n\t\"/app.js\",\n\t\"/app.css\",\n\t\"/manifest.webmanifest\",\n\t\"/favicon.svg\",\n\t\"/favicon-180x180.png\",\n\t\"/favicon-192x192.png\",\n\t\"/favicon-512x512.png\",\n];\n\nself.addEventListener(\"install\", event => {\n\tevent.waitUntil(caches.open(CACHE_NAME).then(cache => cache.addAll(SHELL_URLS)).then(() => self.skipWaiting()));\n});\n\nself.addEventListener(\"activate\", event => {\n\tevent.waitUntil(\n\t\tcaches.keys()\n\t\t\t.then(keys => Promise.all(keys.filter(key => key !== CACHE_NAME).map(key => caches.delete(key))))\n\t\t\t.then(() => self.clients.claim()),\n\t);\n});\n\nself.addEventListener(\"fetch\", event => {\n\tconst request = event.request;\n\tconst url = new URL(request.url);\n\tif (url.origin !== self.location.origin) return;\n\tif (url.pathname.startsWith(\"/api/\") || url.pathname.endsWith(\"/events\")) return;\n\tif (request.method !== \"GET\") return;\n\n\tif (request.mode === \"navigate\") {\n\t\tevent.respondWith(fetch(request).catch(() => caches.match(\"/\").then(response => response ?? Response.error())));\n\t\treturn;\n\t}\n\n\tif (SHELL_URLS.includes(url.pathname)) {\n\t\tevent.respondWith(caches.match(request).then(cached => cached ?? fetch(request)));\n\t}\n});\n", contentType: "text/javascript; charset=utf-8", cacheControl: "no-cache" },
	"/favicon.svg": { body: "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 64 64\">\n  <defs>\n    <linearGradient id=\"g\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n      <stop offset=\"0\" stop-color=\"#ed4abf\" />\n      <stop offset=\".5\" stop-color=\"#9b4dff\" />\n      <stop offset=\"1\" stop-color=\"#5ad8e6\" />\n    </linearGradient>\n  </defs>\n  <rect width=\"64\" height=\"64\" rx=\"12\" fill=\"#0f0a14\" />\n  <path fill=\"url(#g)\" d=\"M14 16h36v8H40v32h-8V24h-6v22h-8V24h-4z\" />\n</svg>\n", contentType: "image/svg+xml", cacheControl: "public, max-age=31536000, immutable" },
